      { q: "¿En qué año pasó el Mariner 4 junto a Marte?", choices: ["1965", "1865", "2015"], hint: "Hace unos 60 años.", explain: "El Mariner 4 pasó junto a Marte en 1965." },
      { q: "¿Cómo envió el Mariner 4 sus fotos a casa?", choices: ["Por correo", "En un cohete pequeñito", "Por radio, en forma de números"], hint: "Un número pequeño para lo oscuro y uno grande para lo claro.", explain: "Envió sus fotos a casa por radio, como largas listas de números." },
      { q: "¿Qué mostraban las fotos?", choices: ["Ciudades y canales", "Cráteres en un mundo seco", "Océanos y bosques"], hint: "Un poco como nuestra Luna.", explain: "Las fotos mostraban un mundo seco lleno de cráteres." },
      { q: "¿Por qué el equipo coloreó los números a mano?", choices: ["Estaban tan emocionados que no podían esperar al ordenador", "Las tizas eran mágicas", "Era un trabajo del colegio"], hint: "El ordenador iba a tardar horas.", explain: "Estaban tan emocionados que no podían esperar, así que colorearon los números a mano." }
